/// The one GPUI entity that owns the editor model. Everything on screen is a function of this.
pub struct App { pub workspace: kate_core::Workspace }

/// GPUI element that paints one view. macOS only. The shape cache lives on the window root.
#[cfg(target_os = "macos")]
pub struct EditorElement { view: kate_core::ViewId, line_height: gpui::Pixels }

/// Shaped lines keyed by line index and buffer revision. The key has no theme revision.
/// On macOS the value is gpui::ShapedLine. On other targets it is a local stub.
pub struct ShapedLineCache { lines: std::collections::HashMap<(u32, kate_text::Revision), ShapedLine> }

/// Frame-time telemetry written to stderr as JSON lines when KATEM5_PROFILE=1.
#[derive(serde::Serialize)]
pub struct FrameSample {
    pub frame: u64,
    pub paint_micros: u64,
    pub first_line: u32,
    pub lines_painted: u32,
    pub highlight_micros: u64,
    pub shape_micros: u64,
    pub draw_micros: u64,
}

/// Open one window and block until quit. On a host that is not macOS, print an error and exit 1.
pub fn run(path: Option<std::path::PathBuf>) -> !;

/// Write a 100,000-line Rust file to `path`.
pub fn write_rust_fixture(path: &std::path::Path) -> std::io::Result<()>;

[workspace.dependencies]
kate-ui = { path = "crates/kate-ui" }
# apps/katem5rust/Cargo.toml: kate-ui = { workspace = true }

license = "GPL-3.0-or-later"

[dependencies]
kate-core = { workspace = true }
kate-text = { workspace = true }
serde = { version = "1", features = ["derive"] }
serde_json = "1"

[target.'cfg(target_os = "macos")'.dependencies]
kate-syntax = { workspace = true }
gpui = { version = "=0.2.2", default-features = false, features = ["font-kit"] }
